local function make(class, parent, props)
    local item = Instance.new(class)
    for key, value in pairs(props or {}) do item[key] = value end
    item.Parent = parent
    return item
end
local function corner(item, radius)
    make("UICorner", item, {CornerRadius = UDim.new(0, radius)})
    return item
end
local function outline(item, color, alpha, thickness)
    return make("UIStroke", item, {Color = color, Transparency = alpha or 0,
        Thickness = thickness or 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border})
end
local function label(parent, text, size, pos, fontSize, bold, z)
    return make("TextLabel", parent, {
        Text = text, Size = size, Position = pos, BackgroundTransparency = 1,
        Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham,
        TextSize = fontSize, TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = z or 5,
    })
end
local function line(parent, x1, y1, x2, y2, weight, color)
    local dx, dy = x2-x1, y2-y1
    local segment = make("Frame", parent, {
        AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromOffset(x1, y1),
        Size = UDim2.fromOffset(math.sqrt(dx*dx+dy*dy), weight),
        Rotation = math.deg(math.atan2(dy, dx)),
        BackgroundColor3 = color, BorderSizePixel = 0, ZIndex = 8,
    })
    corner(segment, weight)
    return segment
end
local iconImages = {}
local iconNodes = {}
local fallbackIcons = {snowflake="*",check="V",x="X",sparkles="N",pumpkin="H",cane="C",minimize="-"}
local function icon(parent, kind, size, color)
    local picture=make("ImageLabel",parent,{Size=UDim2.fromOffset(size,size),
        BackgroundTransparency=1,Image="",ImageColor3=color,
        ScaleType=Enum.ScaleType.Fit,ZIndex=8})
    local fallback=label(picture,fallbackIcons[kind] or "*",
        UDim2.fromScale(1,1),UDim2.fromScale(0,0),size*0.75,true,9)
    fallback.Name="Fallback"
    fallback.TextXAlignment=Enum.TextXAlignment.Center
    fallback.TextColor3=color
    picture.Image=iconImages[kind] or ""
    fallback.Visible=picture.Image==""
    iconNodes[#iconNodes+1]={Picture=picture,Kind=kind,Fallback=fallback}
    return picture
end

