local function decode(encoded)
    encoded=encoded:gsub("%s+","")
    local custom = (crypt and crypt.base64 and crypt.base64.decode)
        or (syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode)
    if type(custom) == "function" then
        local ok, bytes = pcall(custom, encoded)
        if ok and type(bytes) == "string" then return bytes end
    end
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}
    for i=1,#alphabet do lookup[alphabet:sub(i,i)] = i-1 end
    local chunks = {}
    for i=1,#encoded,4 do
        local a,b,c,d = encoded:sub(i,i+3):match("(.)(.)(.)(.)")
        local n = (lookup[a] or 0)*262144 + (lookup[b] or 0)*4096
            + (lookup[c] or 0)*64 + (lookup[d] or 0)
        local first = math.floor(n/65536)%256
        local second = math.floor(n/256)%256
        if c == "=" then chunks[#chunks+1] = string.char(first)
        elseif d == "=" then chunks[#chunks+1] = string.char(first,second)
        else chunks[#chunks+1] = string.char(first,second,n%256) end
    end
    return table.concat(chunks)
end
local function asset(name, data, extension)
    local localAsset = getcustomasset or getsynasset or get_custom_asset
    if type(localAsset) ~= "function" or type(writefile) ~= "function" then return "" end
    local path = "VexloHub_" .. name .. "." .. (extension or "jpg")
    local ok, result = pcall(function()
        if type(isfile) ~= "function" or not isfile(path) then writefile(path, decode(data)) end
        return localAsset(path)
    end)
    return ok and result or ""
end
