local activeTweens={}
local minimized=false
local rainGeneration=0
local rainParticles={Halloween={},Christmas={}}
local rainTweens={}
local function caneBar(parent,x,y,w,h,color,rotation)
    return corner(make("Frame",parent,{Position=UDim2.fromOffset(x,y),
        Size=UDim2.fromOffset(w,h),Rotation=rotation or 0,
        BackgroundColor3=color,BackgroundTransparency=0.26,BorderSizePixel=0,ZIndex=3}),math.min(w,h)/2)
end
local function createRainParticle(themeName)
    local particle=make("Frame",rainLayer,{Size=UDim2.fromOffset(27,31),
        BackgroundTransparency=1,BorderSizePixel=0,Visible=false,ZIndex=3})
    if themeName=="Halloween" then
        local orange=Color3.fromRGB(245,129,59)
        local cream=Color3.fromRGB(255,213,146)
        caneBar(particle,6,9,15,12,orange,22)
        caneBar(particle,2,10,7,9,cream,-24)
        caneBar(particle,19,11,7,9,cream,24)
        caneBar(particle,12,10,3,11,cream,22)
    else
        -- A tiny striped candy cane, drawn from UI shapes so it needs no asset.
        local white=Color3.fromRGB(255,246,235)
        local red=Color3.fromRGB(232,57,76)
        caneBar(particle,13,9,8,25,white)
        caneBar(particle,8,3,12,8,white)
        caneBar(particle,3,5,8,10,white)
        caneBar(particle,13,12,8,4,red,-24)
        caneBar(particle,13,20,8,4,red,-24)
        caneBar(particle,13,28,8,4,red,-24)
        caneBar(particle,5,3,6,4,red,-20)
        caneBar(particle,16,3,5,4,red,24)
    end
    return particle
end
local function stopRain()
    rainGeneration=rainGeneration+1
    for i,tween in pairs(rainTweens) do
        tween:Cancel()
        rainTweens[i]=nil
    end
    for _,group in pairs(rainParticles) do
        for _,particle in ipairs(group) do particle.Visible=false end
    end
end
local function startRain()
    stopRain()
    if minimized or (selected~="Halloween" and selected~="Christmas") then return end
    local season=selected
    local generation=rainGeneration
    local group=rainParticles[season]
    for i=1,10 do
        if not group[i] then group[i]=createRainParticle(season) end
        local particle=group[i]
        local function fall()
            if generation~=rainGeneration or not root.Parent or minimized then return end
            local lane=((i*0.137)+(math.random()*0.09))%0.94+0.02
            particle.Position=UDim2.new(lane,0,0,-40)
            particle.Rotation=math.random(-24,24)
            particle.Visible=true
            local duration=math.random(68,110)/10
            local tween=TweenService:Create(particle,
                TweenInfo.new(duration,Enum.EasingStyle.Linear),{
                    Position=UDim2.new(math.clamp(lane+math.random(-9,9)/100,0.02,0.96),
                        0,1,42),Rotation=particle.Rotation+math.random(-65,65)})
            rainTweens[i]=tween
            tween.Completed:Connect(function(state)
                if state==Enum.PlaybackState.Completed and generation==rainGeneration then
                    particle.Visible=false
                    fall()
                end
            end)
            tween:Play()
        end
        task.delay((i-1)*0.29,fall)
    end
end
local function animate(item, goals, seconds)
    if activeTweens[item] then activeTweens[item]:Cancel() end
    local tween=TweenService:Create(item,TweenInfo.new(seconds or 0.22,
        Enum.EasingStyle.Quad,Enum.EasingDirection.Out),goals)
    activeTweens[item]=tween;tween:Play()
end
local actions={}
local api={OnAction=actions,SetTheme=nil,GetTheme=function() return selected end,
    GetStates=function()
        local state={}
        for _,r in ipairs(rows) do state[r.Name]=r.On end
        return state
    end}
local function paintRow(r,motion)
    local t=themes[selected]
    r.Card.BackgroundColor3=t.card
    r.Stroke.Color=r.On and t.accent or t.stroke
    r.Stroke.Transparency=r.On and 0.14 or 0.58
    r.Icon.BackgroundColor3=t.accentSoft
    r.Title.TextColor3=t.text
    r.Status.TextColor3=r.On and t.accent or t.muted
    r.Status.Text=r.On and "Preview on" or "Preview off"
    r.Track.BackgroundColor3=r.On and t.accentSoft or t.surface
    r.Knob.BackgroundColor3=r.On and t.accent or t.muted
    r.KnobGlyph.Text=r.On and t.knob or ""
    r.KnobGlyph.TextColor3=t.background
    local pos=r.On and UDim2.fromOffset(26,3) or UDim2.fromOffset(3,3)
    if motion then animate(r.Knob,{Position=pos},0.25) else r.Knob.Position=pos end
    r.Vector.ImageColor3=t.accent
    local fallback=r.Vector:FindFirstChild("Fallback")
    if fallback then fallback.TextColor3=t.accent end
end
local function setTheme(name)
    if not themes[name] then return end
    selected=name
    local t=themes[name]
    shell.BackgroundColor3=t.background
    shellStroke.Color=t.stroke
    shellGrad.Color=ColorSequence.new(t.background,t.second)
    veil.BackgroundColor3=t.background
    topLight.BackgroundColor3=t.accent
    logo.BackgroundColor3=t.accentSoft
    logoText.TextColor3=t.text
    title.TextColor3=t.text
    subtitle.TextColor3=t.muted
    mini.BackgroundColor3=t.accentSoft
    divider.BackgroundColor3=t.stroke
    eyebrow.TextColor3=t.accent
    description.TextColor3=t.muted
    section.TextColor3=t.accent
    lineBottom.BackgroundColor3=t.stroke
    footer.TextColor3=t.accent
    note.TextColor3=t.muted
    for themeName, item in pairs(themeButtons) do
        local on=name==themeName
        item.Button.BackgroundColor3=on and t.accentSoft or t.surface
        item.Border.Color=on and t.accent or t.stroke
        item.Border.Transparency=on and 0.05 or 0.72
        item.Caption.TextColor3=on and t.text or t.muted
        item.Glyph.ImageColor3=on and t.accent or t.muted
        local fallback=item.Glyph:FindFirstChild("Fallback")
        if fallback then fallback.TextColor3=item.Glyph.ImageColor3 end
    end
    for _,r in ipairs(rows) do paintRow(r,false) end
    backdrop.Visible=name~="Neon" and backgrounds[name]~=""
    backdrop.Image=backgrounds[name] or ""
    veil.BackgroundTransparency=name=="Neon" and 0.32 or 0.38
    startRain()
    if type(writefile)=="function" then
        pcall(writefile,configPath,HttpService:JSONEncode({theme=name}))
    end
end
api.SetTheme=setTheme
for name,item in pairs(themeButtons) do
    item.Button.Activated:Connect(function() setTheme(name) end)
end
for _,r in ipairs(rows) do
    r.Hit.Activated:Connect(function()
        r.On=not r.On
        paintRow(r,true)
        local callback=actions[r.Name]
        if type(callback)=="function" then
            local ok,err=pcall(callback,r.On)
            if not ok then warn("[Vexlo] "..r.Name..": "..tostring(err)) end
        end
    end)
end
-- Images are decoded after the UI is visible. Unsupported local asset APIs
-- leave a themed gradient in place and never block the buttons.
task.spawn(function()
    for kind,encoded in pairs(ICON_DATA) do
        iconImages[kind]=asset("icon_"..kind.."_v2",encoded,"png")
    end
    for _,entry in ipairs(iconNodes) do
        if entry.Picture.Parent then
            entry.Picture.Image=iconImages[entry.Kind] or ""
            entry.Fallback.Visible=entry.Picture.Image==""
        end
    end
    backgrounds.Halloween=asset("Halloween",DATA_HALLOWEEN)
    backgrounds.Christmas=asset("Christmas",DATA_CHRISTMAS)
    if root.Parent then setTheme(selected) end
end)
setTheme(selected)
local expandedSize=shell.Size
mini.Activated:Connect(function()
    minimized=not minimized
    startRain()
    body.Visible=not minimized
    animate(shell,{Size=minimized and UDim2.fromOffset(expandedSize.X.Offset,79)
        or expandedSize},0.28)
    miniIcon.Visible=not minimized
    mini.Text=minimized and "+" or ""
    mini.TextColor3=themes[selected].text
    mini.Font=Enum.Font.GothamBold;mini.TextSize=20
end)
local dragInput,dragStart,origin
header.InputBegan:Connect(function(input)
    if input.UserInputType==Enum.UserInputType.MouseButton1 or
        input.UserInputType==Enum.UserInputType.Touch then
        dragInput=input;dragStart=input.Position;origin=shell.Position
    end
end)
header.InputEnded:Connect(function(input)
    if input==dragInput then dragInput=nil end
end)
local inputChangedConnection=UserInputService.InputChanged:Connect(function(input)
    if dragInput and (input==dragInput or
        input.UserInputType==Enum.UserInputType.MouseMovement) then
        local delta=input.Position-dragStart
        shell.Position=UDim2.new(origin.X.Scale,origin.X.Offset+delta.X,
            origin.Y.Scale,origin.Y.Offset+delta.Y)
    end
end)
function api.Destroy()
    stopRain()
    inputChangedConnection:Disconnect()
    root:Destroy()
    if _G.VexloVisual==api then _G.VexloVisual=nil end
end
_G.VexloVisual=api
return api
